package com.bank.merge.service;

import com.bank.merge.dto.MergeReport;
import com.bank.merge.model.Employee;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.*;
import java.util.stream.*;

@Service
@Slf4j
public class EmployeeMergeService {

    // HQ records
    private final List<Employee> hqList = List.of(
        new Employee("E001", "Rajesh Kumar",  "TRADING",    new BigDecimal("1200000")),
        new Employee("E002", "Priya Sharma",  "RISK",       new BigDecimal("1000000")),
        new Employee("E003", "Amit Patel",    "TRADING",    new BigDecimal("1500000")),
        new Employee("E004", "Deepa Reddy",   "OPERATIONS", new BigDecimal("900000"))
    );

    // Branch updates (E002 and E003 have updated salary, E005 is new)
    private final List<Employee> branchList = List.of(
        new Employee("E002", "Priya Sharma",  "RISK",       new BigDecimal("1100000")),  // salary updated!
        new Employee("E003", "Amit R. Patel", "COMPLIANCE", new BigDecimal("1600000")),  // name + dept + salary changed!
        new Employee("E005", "Vikram Singh",  "RISK",       new BigDecimal("1800000"))   // new employee
    );

    public MergeReport merge() {
        Map<String, List<String>> strategies = new LinkedHashMap<>();

        // Count duplicates
        Set<String> hqIds = hqList.stream().map(Employee::empId).collect(Collectors.toSet());
        Set<String> branchIds = branchList.stream().map(Employee::empId).collect(Collectors.toSet());
        long duplicates = branchIds.stream().filter(hqIds::contains).count();

        // ═══ STRATEGY 1: KEEP-EXISTING (HQ wins) ═══
        List<Employee> keepExisting = Stream.concat(hqList.stream(), branchList.stream())
            .collect(Collectors.toMap(Employee::empId, e -> e,
                (existing, incoming) -> existing))   // HQ record kept for E002, E003
            .values().stream()
            .sorted(Comparator.comparing(Employee::empId))
            .toList();
        strategies.put("KEEP_EXISTING (HQ wins)", keepExisting.stream()
            .map(this::format).toList());

        // ═══ STRATEGY 2: KEEP-INCOMING (branch wins) ═══
        List<Employee> keepIncoming = Stream.concat(hqList.stream(), branchList.stream())
            .collect(Collectors.toMap(Employee::empId, e -> e,
                (existing, incoming) -> incoming))   // branch record wins for E002, E003
            .values().stream()
            .sorted(Comparator.comparing(Employee::empId))
            .toList();
        strategies.put("KEEP_INCOMING (branch wins)", keepIncoming.stream()
            .map(this::format).toList());

        // ═══ STRATEGY 3: DEEP-MERGE (combine fields) ═══
        List<Employee> deepMerged = Stream.concat(hqList.stream(), branchList.stream())
            .collect(Collectors.toMap(Employee::empId, e -> e,
                (hq, branch) -> new Employee(
                    hq.empId(),                // keep ID
                    branch.name(),             // take updated name from branch
                    hq.department(),           // keep HQ department
                    branch.salary())))         // take updated salary from branch
            .values().stream()
            .sorted(Comparator.comparing(Employee::empId))
            .toList();
        strategies.put("DEEP_MERGE (name+salary from branch, dept from HQ)", deepMerged.stream()
            .map(this::format).toList());

        return new MergeReport(hqList.size(), branchList.size(), (int) duplicates, strategies);
    }

    private String format(Employee e) {
        return e.empId() + " " + e.name() + " [" + e.department() + "] Rs." + e.salary();
    }
}
