package com.bank.merge.service;

import com.bank.merge.model.Employee;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.*;
import java.util.stream.*;
import static org.assertj.core.api.Assertions.*;

class MergeListsTest {

    @Test
    void keepExistingPreservesFirstOccurrence() {
        var list1 = List.of(new Employee("E1", "Rajesh", "TRADING", BigDecimal.valueOf(100)));
        var list2 = List.of(new Employee("E1", "Rajesh Updated", "RISK", BigDecimal.valueOf(200)));

        Employee merged = Stream.concat(list1.stream(), list2.stream())
            .collect(Collectors.toMap(Employee::empId, e -> e, (old, nw) -> old))
            .get("E1");

        assertThat(merged.name()).isEqualTo("Rajesh");         // kept existing
        assertThat(merged.salary()).isEqualByComparingTo("100"); // kept existing
    }

    @Test
    void keepIncomingUsesLatest() {
        var list1 = List.of(new Employee("E1", "Rajesh", "TRADING", BigDecimal.valueOf(100)));
        var list2 = List.of(new Employee("E1", "Rajesh Updated", "RISK", BigDecimal.valueOf(200)));

        Employee merged = Stream.concat(list1.stream(), list2.stream())
            .collect(Collectors.toMap(Employee::empId, e -> e, (old, nw) -> nw))
            .get("E1");

        assertThat(merged.name()).isEqualTo("Rajesh Updated");  // took incoming
        assertThat(merged.salary()).isEqualByComparingTo("200"); // took incoming
    }

    @Test
    void deepMergeCombinesFields() {
        var list1 = List.of(new Employee("E1", "Rajesh", "TRADING", BigDecimal.valueOf(100)));
        var list2 = List.of(new Employee("E1", "Rajesh K.", "RISK", BigDecimal.valueOf(200)));

        Employee merged = Stream.concat(list1.stream(), list2.stream())
            .collect(Collectors.toMap(Employee::empId, e -> e,
                (old, nw) -> new Employee(old.empId(), nw.name(), old.department(), nw.salary())))
            .get("E1");

        assertThat(merged.name()).isEqualTo("Rajesh K.");       // from incoming
        assertThat(merged.department()).isEqualTo("TRADING");    // from existing
        assertThat(merged.salary()).isEqualByComparingTo("200"); // from incoming
    }

    @Test
    void newEmployeesFromBothListsIncluded() {
        var list1 = List.of(new Employee("E1", "A", "D1", BigDecimal.ONE));
        var list2 = List.of(new Employee("E2", "B", "D2", BigDecimal.TEN));

        Map<String, Employee> merged = Stream.concat(list1.stream(), list2.stream())
            .collect(Collectors.toMap(Employee::empId, e -> e, (o, n) -> o));

        assertThat(merged).containsKeys("E1", "E2");  // both included
    }

    @Test
    void withoutMergeFunctionThrowsOnDuplicate() {
        var list1 = List.of(new Employee("E1", "A", "D1", BigDecimal.ONE));
        var list2 = List.of(new Employee("E1", "B", "D2", BigDecimal.TEN));

        assertThatThrownBy(() ->
            Stream.concat(list1.stream(), list2.stream())
                .collect(Collectors.toMap(Employee::empId, e -> e)))  // NO merge function!
            .isInstanceOf(IllegalStateException.class)
            .hasMessageContaining("Duplicate key");
    }
}
